# Frederic L. Billon, Annals of St. Louis in its Territorial Days, from 1804 to 1821 (Saint-Louis, 1888), PDF du Drive
# de l'auteur. L'outil du Drive n'en livre que le début (jusqu'à la section sur l'arpentage de 1817) : la suite est à découper.
# Corpus « Recherches », préfixe BL88.
from commun import Corpus
BL = "Billon, Frederic L. (1888), Annals of St. Louis in its Territorial Days, from 1804 to 1821, Saint-Louis, imprimé pour l'auteur"
C = Corpus('Recherches', 'BL88', BL, page_fmt='p. {}')
F = C.F
SL = (-90.1866, 38.6268)
F('01', "Saint-Louis : le premier grand jury américain, chez Émilien Yosti, en majorité francophone (18 décembre 1804)", 'evenement', '1804-12-18/1804-12-20', *SL, 'c', ['Auguste Chouteau', 'Jacques Clamorgan', 'David Delaunay', 'Antoine Soulard', 'Bernard Pratte', 'Joseph Brazeau', 'Antoine Vincent', 'Sylvestre Labadie', 'Joseph M. Papin', 'Jean-Baptiste Trudeau', 'François-Marie Benoist', 'Pierre Didier', 'Émilien Yosti', 'Guillaume Hébert', 'Hyacinthe Église', 'André Andreville', 'Hyacinthe Saint-Cyr', 'Louis Brazeau', 'Charles Desjarlais', 'Charles Gratiot'],
  "La première cour des sessions trimestrielles du district de Saint-Louis se réunit le 18 décembre 1804 dans la maison d'Émilien Yosti. Sur le banc siègent Auguste Chouteau, Jacques Clamorgan, David Delaunay et James Mackay. Le shérif présente 24 grands jurés, dont une majorité de francophones : Soulard, Pratte, Brazeau, Vincent, Labadie, Papin, Trudeau, Benoist, Didier, Yosti, Hébert, Église, Andreville, Saint-Cyr, entre autres. Les quatre absents sont mis à l'amende de cinq dollars. Charles Desjarlais devient connétable de Florissant. La cour loue à Clamorgan, pour quinze dollars par mois, une maison qui servira de prison.",
  '9-10')
F('02', "Saint-Louis : un juré qui ne parlait pas anglais à la première exécution du comté (août-septembre 1809)", 'evenement', '1809-08-21/1809-09-16', *SL, 'c', ['Alexis Lalande', 'Antoine Barada', 'Michel Honoré', 'Auguste Chouteau', 'Jean-Baptiste-Charles Lucas'],
  "John Long fils, qui avait tué son beau-père au moulin de Long (canton de Bonhomme), est jugé le 21 août 1809 par la cour d'Oyer and Terminer, où siège Auguste Chouteau comme assesseur. Il est condamné et pendu le 16 septembre, première exécution du comté. Parmi les douze jurés figurent Antoine Barada, Michel Honoré et Alexis Lalande. Billon note que Lalande jura plus tard qu'il ne parlait ni ne comprenait un mot d'anglais.",
  '15-16')
F('03', "Saint-Louis : l'association de William Clark, Manuel Lisa et Sylvestre Labadie pour la traite du haut Missouri (1809)", 'commerce', '1809', *SL, 'c', ['Manuel Lisa', 'Sylvestre Labadie', 'William Clark', 'George Drouillard'],
  "Billon, citant la Gazette, rapporte qu'au début de 1809 William Clark, Manuel Lisa et Sylvestre Labadie s'associent avec un capital de 27 000 dollars (9 000 chacun) pour traiter avec les nations du haut Missouri jusqu'aux montagnes. Il donne à cette société le nom d'American Fur Company. Deux ans plus tôt, au printemps 1807, Lisa et George Drouillard, ancien de l'expédition Lewis et Clark, avaient remonté le Missouri avec une cargaison de 16 000 dollars.",
  '32-33', "Billon appelle cette société American Fur Company ; il s'agit des débuts de la Missouri Fur Company (St. Louis Missouri Fur Company, 1809).")
F('04', "Herculaneum (Missouri) : la tour à plomb de chasse de Jean-Nicolas Maclot, la première à l'ouest des Alleghanys (1809-1815)", 'etablissement', '1809/1815', -90.3790, 38.2650, 'c', ['Jean-Nicolas Maclot', 'Marie-Thérèse Gratiot', 'Charles Gratiot'],
  "Né à Metz le 18 juin 1767, embastillé pour ses opinions avant la Révolution, Jean-Nicolas Maclot passe à Londres, où il apprend la bijouterie, puis à Philadelphie, et s'établit à Saint-Louis en 1804 avec un fonds de marchandises. Il épouse le 16 août 1806 Marie-Thérèse, fille de Charles Gratiot. En 1809, il élève sur la falaise au sud du nouveau village d'Herculaneum, à 32 milles en aval de Saint-Louis, une tour pour fabriquer le plomb de chasse et le plomb en barres, la première fonderie de ce genre à l'ouest des Alleghanys, en service dès novembre 1809. Il s'installe sur une ferme voisine en 1811 ; sa femme meurt à Sainte-Geneviève le 26 février 1815.",
  '177-178', "Point à la falaise sud d'Herculaneum (comté de Jefferson). Plusieurs tours à plomb s'y succèdent ensuite.")
F('05', "Saint-Louis, rue Second : l'académie de jeunes filles de Madame Pescay, réfugiée de Saint-Domingue (1810-1822)", 'etablissement', '1810/1822', -90.1870, 38.6250, 'c', ['Angélique La Grange Pescay', 'Michel Tesson', 'Julius Pescay', 'George Pescay'],
  "Née Angélique La Grange, d'une vieille famille de France, veuve de François Pescay, de Saint-Domingue, réfugiée à Philadelphie après l'insurrection de 1793, Madame Pescay arrive à Saint-Louis en 1810 avec ses fils et Michel Tesson, autre réfugié de l'île. Son aîné George se noie en janvier 1811 quand coule le bateau à quille qui portait leur plomb à La Nouvelle-Orléans. Elle bâtit alors une maison rue Second et ouvre en mai 1812 une académie de jeunes filles, la première de l'Ouest, fréquentée par les premières familles ; elle la tient environ quatre ans, puis reprend le commerce et part pour Pensacola en 1822.",
  '256-259', "Point schématique rue Second.")
F('06', "Saint-Louis : Augustin Guibord, de Mascouche, arrivé avec des traiteurs de la baie d'Hudson (1804-1860)", 'personnage', '1804/1860-09-12', -90.1880, 38.6280, 'c', ['Augustin Guibord', 'Marie-Catherine Lacroix', 'Henri Guibor', 'Augustus Guibord'],
  "Né à Mascouche, près de Montréal, le 12 mai 1785, Augustin Guibord gagne Saint-Louis à l'automne 1804, à 19 ans, avec un parti de traiteurs de la Compagnie de la baie d'Hudson, sans le consentement de ses parents. Il épouse le 6 juillet 1811 Marie-Catherine Lacroix, fille de Joseph Lacroix et d'Hélène Bissonnet, sert dans les forces américaines pendant la guerre de 1812 et meurt à Saint-Louis le 12 septembre 1860. Son fils Augustus meurt au Colorado en 1850 ; un autre, Henri Guibor, combat au Mexique en 1846-1847, puis commande une batterie d'artillerie confédérée.",
  '212-213', "Point schématique dans la vieille ville.")
F('07', "Saint-Louis : Antoine Chenié, de Pointe-Claire, commis de traite devenu boulanger de la rue du Marché (1795-1842)", 'personnage', '1795/1842-05-26', -90.1885, 38.6265, 'c', ['Antoine Chenié', 'Marie-Thérèse Papin', 'Pierre Chouteau'],
  "Né à Pointe-Claire le 14 avril 1768, Antoine Chenié fait ses classes à Montréal, sert plusieurs années la traite canadienne aux chutes du Niagara, puis arrive à Saint-Louis en 1795 comme commis d'un grand traiteur du Missouri. Marié le 26 octobre 1805 à Marie-Thérèse Papin, fille de Joseph-Marie Papin, il quitte la traite pour ouvrir une boulangerie : le 15 octobre 1808, il achète de Pierre Chouteau la moitié sud du bloc 33, rue du Marché, avec une grande maison de pierre de 48 pieds sur 30. Il meurt le 26 mai 1842 ; sa fille Louise épouse Bernard Pratte fils.",
  '211-212', "Point à la rue du Marché (Market Street), entre Main et Church.")
F('08', "Saint-Louis : René Paul, de Saint-Domingue, associé de Berthold, et son fils le général Gabriel René Paul (1809-1886)", 'famille', '1809/1886', -90.1878, 38.6262, 'c', ['René Paul', 'Barthélemy Berthold', 'Gabriel René Paul', 'Edmund Paul'],
  "Fils d'Eustache Paul, de Cap-Français, René et Gabriel Paul font leurs études à Paris pendant l'insurrection de 1793 ; leur père meurt en mer en fuyant l'île. Arrivés aux États-Unis en 1802, ils s'établissent à Baltimore ; en 1809, René Paul vient à Saint-Louis avec Barthélemy Berthold. Colonel, il meurt en 1851. Son fils Gabriel René Paul, sorti de West Point en 1834, épouse à Fort Gibson la fille du colonel Whistler, devient général et, laissé pour mort et aveugle à Gettysburg, meurt à Washington en 1886 ; un autre fils, Edmund, épouse une St. Vrain et commande une compagnie de la St. Louis Legion au Mexique.",
  '235-238', "Point schématique dans la vieille ville.")
F('09', "Saint-Louis : l'académie des Perdreauville, exilés de l'Empire, et l'école de danse de Durocher (1818-1820)", 'etablissement', '1818-09/1820', -90.1868, 38.6245, 'c', ['René Perdreauville', 'Marie-Antoinette-Adèle Perdreauville', 'Jean-Pierre Gratiot', 'Durocher', 'Lucien Dumaine'],
  "Chassée de France par l'abdication de Napoléon, la famille de René Perdreauville, ancien officier de la maison de l'Empereur, arrive à Saint-Louis à l'été 1818. En septembre, Madame Perdreauville et ses filles ouvrent une académie de jeunes filles (musique, et danse enseignée par le maître Durocher) ; l'aînée épouse le 18 novembre 1819 Jean-Pierre Gratiot, puis la famille part pour La Nouvelle-Orléans en 1820. Billon évoque aussi le Charentais Lucien Dumaine, commis chez Berthold et Chouteau dès 1819, puis marchand, et le docteur Paul-Malo Gebert, médecin de la population française de 1819 à 1826.",
  '312-314, 344', "Point schématique dans la vieille ville.")
F('10', "Saint-Louis : les sept fils de Joseph-Marie Papin et de Marie-Louise Chouteau (vers 1780-1853)", 'famille', '1780/1853', -90.1876, 38.6268, 'c', ['Joseph-Marie Papin', 'Marie-Louise Chouteau', 'Alexandre Laforce Papin', 'Hypolite Leber Papin', 'Sylvestre Vilray Papin', 'Pierre-Didier Papin', "Théodore d'Artigny Papin", 'Régis Loisel'],
  "Billon dresse la généalogie des sept fils de Joseph-Marie Papin et de Marie-Louise Chouteau, sœur d'Auguste : Joseph (1780-1850) ; Alexandre Laforce (1782-1849), marié à Julie Brazeau, dont le fils Alexandre est tué au Nouveau-Mexique ; Hypolite Leber (1787-1842) et Sylvestre Vilray (1794-1828), qui épousent deux filles du traiteur Régis Loisel ; Pierre-Mellicourt (1793-1849) ; Pierre-Didier (1798-1853), traiteur du haut Missouri, marié à Catherine-Louise Cerré ; Théodore d'Artigny (1799-1851), marié à une Duchouquette. Une fille, Marie-Thérèse, épouse Antoine Chenié.",
  '183-186', "Point schématique dans la vieille ville. Pierre-Didier Papin a ses propres fiches (F-papin).")
F('11', "Saint-Louis, extrémité nord du village : la forge de Gémenin Beauvais, puis Sainte-Geneviève (1799-1841)", 'etablissement', '1799-12-05/1841', -90.1840, 38.6340, 'c', ['Gémenin Beauvais', 'Charles de Hault de Lassus'],
  "Né près de Montréal vers 1770, venu jeune à Saint-Louis, Gémenin Beauvais reçoit du gouverneur De Lassus, le 5 décembre 1799, une demi-île vacante à l'extrémité nord du village, où il bâtit une forge (angle nord-ouest des rues Main et Cherry). Il la vend en 1807 pour Sainte-Geneviève, où il épouse vers 1808 une Aubuchon et où naissent ses enfants, puis revient mourir à Saint-Louis en 1841, à 71 ans.",
  '187', "Point à l'angle des rues Main et Cherry (nord de la vieille ville).")
fiches = C.fiches
